// Extract search parameters from webhook payload
const body = $input.first().json.body || $input.first().json.query || {};
const query = body.query || 'Software Engineer';
const location = body.location || 'India';
const department = body.department || 'CSE/IT';

return [{
  json: {
    query,
    location,
    department
  }
}];
